(function () {

  console.log(
    "========== PPT MEDIA PLAYER LOADED =========="
  );

  function handleMedia(
    button,
    event
  ) {

    if (!button) return;

    var mediaId =
      button.getAttribute(
        "data-media-id"
      );

    var mediaType =
      button.getAttribute(
        "data-media-type"
      );

    if (
      !mediaId ||
      !mediaType
    ) {
      return;
    }

    var media =
      document.getElementById(
        mediaId
      );

    if (!media) {
      console.error(
        "MEDIA ELEMENT NOT FOUND:",
        mediaId
      );

      return;
    }

    console.log(
      "MEDIA TRIGGERED:",
      mediaId,
      mediaType
    );

    event.preventDefault();
    event.stopImmediatePropagation();

    if (
      mediaType === "audio"
    ) {

      if (
        media.paused
      ) {

        if (
          media.ended
        ) {
          media.currentTime =
            0;
        }

        media.play()
          .then(
            function () {
              console.log(
                "AUDIO PLAYING SUCCESSFULLY"
              );

              button.setAttribute(
                "data-playing",
                "true"
              );
            }
          )
          .catch(
            function (
              error
            ) {
              console.error(
                "AUDIO PLAYBACK FAILED:",
                error
              );
            }
          );

      } else {

        media.pause();

        button.setAttribute(
          "data-playing",
          "false"
        );
      }

      return;
    }

    if (
      mediaType === "video"
    ) {

      if (
        media.paused
      ) {

        media.play()
          .then(
            function () {
              console.log(
                "VIDEO PLAYING SUCCESSFULLY"
              );
            }
          )
          .catch(
            function (
              error
            ) {
              console.error(
                "VIDEO PLAYBACK FAILED:",
                error
              );
            }
          );

      } else {
        media.pause();
      }

      return;
    }
  }

  function attachMediaHandlers() {

    var buttons =
      document.querySelectorAll(
        '.media-action-surface[data-media-id]'
      );

    console.log(
      "MEDIA BUTTONS FOUND:",
      buttons.length
    );

    buttons.forEach(
      function (
        button
      ) {

        button.style.cursor =
          "pointer";

        button.addEventListener(
          "pointerdown",
          function (
            event
          ) {

            console.log(
              "MEDIA POINTERDOWN:",
              button.getAttribute(
                "data-media-id"
              )
            );

            handleMedia(
              button,
              event
            );

          },
          true
        );

        button.addEventListener(
          "click",
          function (
            event
          ) {

            console.log(
              "MEDIA CLICK:",
              button.getAttribute(
                "data-media-id"
              )
            );

            event.preventDefault();
            event.stopImmediatePropagation();

          },
          true
        );

      }
    );
  }

  if (
    document.readyState ===
    "loading"
  ) {

    document.addEventListener(
      "DOMContentLoaded",
      attachMediaHandlers
    );

  } else {
    attachMediaHandlers();
  }

  console.log(
    "========== MEDIA PLAYER READY =========="
  );

})();
